-- Retail weaponskill list (LandSandBoat sql/weapon_skills.sql).
-- skill is xi.skill: 1 h2h, 2 dagger, 3 sword, 4 g.sword, 5 axe, 6 g.axe, 7 scythe,
-- 8 polearm, 9 katana, 10 g.katana, 11 club, 12 staff, 25 archery, 26 marksmanship, 27 throwing.
CREATE TABLE IF NOT EXISTS weapon_skills (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  skill INTEGER NOT NULL,
  skill_level INTEGER NOT NULL DEFAULT 0,
  element INTEGER NOT NULL DEFAULT 0,
  animation INTEGER NOT NULL DEFAULT 0);
